Definition fini_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - 304, bv_unsigned sp); (0x22ccd0, 0x22ccd1); (0x22cc80, 0x22cc88); (0x22dbf0, 0x22dbf8);
              (XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI); (0x762a20, 0x762a23); (0x7629c0, 0x7629c2)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp).

Lemma fini_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo : Z) (o1 o2 o3 o4 o5 : byte) (flag dso : word),
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 304 -> 0x800f0000 <= lo ->
  ro_cells asegs m 0x20b038 [C8 (Z_to_bv 64 0xfa7ec); C8 (Z_to_bv 64 0x9fb54)] ->
  ro_cells asegs m 0x212658 [C8 (Z_to_bv 64 0x20b048); C8 (Z_to_bv 64 0x20b038)] ->
  ro_cells asegs m 0x2117a8 [C8 (Z_to_bv 64 0x1f2e24); C8 (Z_to_bv 64 0)] ->
  ro_cells asegs m 0x2136c0 [C8 dso] ->
  ro_cells asegs m 0x212480 [C8 (Z_to_bv 64 0x216510); C8 (Z_to_bv 64 0x22cc50)] ->
  rw_cells asegs m 0x22ccd0 [C1 (Z_to_bv 8 0)] ->
  rw_cells asegs m 0x22cc80 [C8 flag] -> bv_unsigned flag <> 0 ->
  unreg_got m ->
  ro_cells asegs m 0x22db50 [C4 (Z_to_bv 64 1)] ->
  rw_cells asegs m 0x22dbf0 [C8 (Z_to_bv 64 0)] ->
  ro_cells asegs m 0x230338 [C8 (Z_to_bv 64 0x7fff8000)] ->
  rw_cells asegs m 0x231018 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x22fb9c [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x2c1ee0 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0x213938 [C8 (Z_to_bv 64 0x203df0)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  gds_at m 0x216510 asan_gds ->
  rw_cells asegs m 0x762a20 [C1 o1] -> rw_cells asegs m 0x7629c0 [C1 o2] -> rw_cells asegs m 0x7629c1 [C1 o3] -> rw_cells asegs m 0x762a21 [C1 o4] -> rw_cells asegs m 0x762a22 [C1 o5] ->
  mem_inv asegs m ->
  evt asegs (fini_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
